
const tasks=[{"id":"45","name":"벽체 보드 설치","kind":"AI 관측","origin":"이번 주 시작","date":"02.17 - 02.23","status":"관측 검토 대기","tone":"neutral","thumb":"assets/sample-wall-current.jpg"},{"id":"39","name":"피팅룸 조명","kind":"현장 제출","origin":"이번 주 시작","date":"02.16 - 02.20","status":"완료 확인 요청","tone":"request","thumb":"assets/sample-lighting.jpg"},{"id":"40","name":"계산대 벽체 골조","kind":"현장 제출","origin":"이번 주 시작","date":"02.16 - 02.18","status":"완료 확인","tone":"confirmed","thumb":"assets/sample-frame-after.jpg"}],photos={"lighting":"assets/sample-lighting.jpg","counterBefore":"assets/sample-frame-before.jpg","counterAfter":"assets/sample-frame-after.jpg","wallBefore":"assets/sample-wall-before.jpg","wallAfter":"assets/sample-wall-current.jpg","wallOverlay":"assets/sample-wall-analysis.jpg"},resubmission={"attempt":2,"reviewedAt":"02.19 16:40","reason":"일부 조명의 점등 상태가 보이지 않아 완료 여부를 확인하기 어렵습니다. 전체 조명이 켜진 상태로 다시 촬영해 주세요."};let wallView="analysis";let selected=new URLSearchParams(location.search).get('task')||'39';if(!tasks.some(t=>t.id===selected))selected='39';let lightConfirmed=false;const rejectionReasons={};
function notify(text){const t=document.querySelector('#toast');t.textContent=text;t.style.display='block';setTimeout(()=>t.style.display='none',2300);}
function photo(src,label,date,id=''){return '<figure class="photo"><img '+(id?'id="'+id+'"':'')+' src="'+src+'" alt="'+label+'"><figcaption><strong>'+label+'</strong><span>'+date+'</span></figcaption></figure>';}
function render(){document.querySelector('#task-list').innerHTML=tasks.map(t=>'<button class="task '+(selected===t.id?'selected':'')+'" data-task="'+t.id+'"><div class="task-body"><img src="'+t.thumb+'" alt="'+t.name+'"><div><div class="task-id">ID '+t.id+'</div><div class="task-name">'+t.name+'</div><div class="task-kind">'+t.kind+(t.id==='39'?' · 재제출 2차':'')+'</div></div></div><div class="task-origin">'+t.origin+'</div><div class="task-bottom"><span class="tag '+(t.id==='39'&&lightConfirmed?'confirmed':t.tone)+'">'+(t.id==='39'&&lightConfirmed?'완료 확인':t.status)+'</span><span class="task-date">'+t.date+'</span></div></button>').join('');document.querySelectorAll('[data-task]').forEach(e=>e.onclick=()=>{selected=e.dataset.task;render();});
const t=tasks.find(x=>x.id===selected);let state=t.id==='39'&&lightConfirmed?'완료 확인':t.status,tone=t.id==='39'&&lightConfirmed?'confirmed':t.tone,body='',note='',actions='';
if(selected==='39'){body='<div class="photo-grid single">'+photo(photos.lighting,'이번 주 완료 증빙 · 현장 제출','02.20 · 생성 예시')+'</div><div class="metrics"><div class="metric"><div class="metric-label">현장 담당자 보고</div><div class="metric-value">조명 설치·점등 완료</div></div><div class="metric"><div class="metric-label">본사 완료 확인</div><div class="metric-value '+(lightConfirmed?'confirmed-text':'request-text')+'">'+(lightConfirmed?'완료 확인':'확인 요청 접수 · 대기')+'</div></div></div>';note='이번 주에 시작해 같은 주에 마무리한 작업의 완료 증빙입니다.';actions='<button class="secondary" id="reject">반려</button><button class="confirm-button" id="accept">'+(lightConfirmed?'완료 확인됨':'완료 확인')+'</button>';}
else if(selected==='40'){body='<div class="photo-grid">'+photo(photos.counterBefore,'착수 전 참고','02.15 · 생성 예시')+photo(photos.counterAfter,'골조 설치 완료','02.18 · 생성 예시')+'</div><div class="metrics"><div class="metric"><div class="metric-label">현장 담당자 보고</div><div class="metric-value">벽체 골조 설치 완료</div></div><div class="metric"><div class="metric-label">본사 검토 결과</div><div class="metric-value confirmed-text">완료 확인 · 02.18</div></div></div>';note='계획은 원본 간트의 02.16~02.18입니다. 착수 전 참고 사진을 비교하며, 이번 주 시작 작업의 주간 보고에는 지난주 설명을 넣지 않습니다.';actions='<button class="secondary" id="history">검토 이력 보기</button>';}
else{body='<div class="photo-tabs"><button class="'+(wallView==='analysis'?'active':'')+'" id="analysis-view-tab">원본·분석 결과</button><button class="'+(wallView==='timeline'?'active':'')+'" id="timeline-view-tab">날짜별 변화</button></div><div class="photo-grid analysis">'+(wallView==='analysis'?photo(photos.wallAfter,'원본 · 분석 적용 전','02.20 · 고정 카메라','original-photo')+photo(photos.wallOverlay,'AI 분석 표시 · 적용 후','02.20 · 같은 사진','overlay-photo'):photo(photos.wallBefore,'착수 전 기준 사진','02.16 · 고정 카메라','baseline-photo')+photo(photos.wallAfter,'이번 주 최신','02.20 · 고정 카메라','latest-photo'))+'</div>'+(wallView==='analysis'?'<div class="analysis-legend"><span><i style="background:#36a974"></i>설치</span><span><i style="background:#d36f67"></i>미설치</span><span><i style="background:#939393"></i>인식 불가</span></div>':'')+'<div class="metrics"><div class="metric"><div class="metric-label">왼쪽 벽 W01 · 설치 관측률</div><div class="metric-value numeric">78.50%</div><div class="bar"><span style="width:78.50%"></span></div></div><div class="metric"><div class="metric-label">오른쪽 벽 W02 · 설치 관측률</div><div class="metric-value numeric">82.00%</div><div class="bar"><span style="width:100%"></span></div></div></div>';note='설치 ÷ (설치 + 미설치), 인식 불가 제외 · 관측 결과 수락과 작업 완료 확인은 구분합니다.';actions='<button class="secondary" id="reject">반려</button><button class="primary" id="accept">관측 결과 수락</button>';}
document.querySelector('#detail').innerHTML='<div class="detail-head"><h2>'+t.name+'</h2><span class="tag '+tone+'">'+state+'</span></div><div class="detail-sub">ID '+t.id+' · '+t.date+' · '+t.origin+' · '+t.kind+(selected==='39'?' · 재제출 '+resubmission.attempt+'차':'')+'</div>'+(selected==='39'||rejectionReasons[selected]?'<section class="review-return" id="rejection-reason"><div class="review-return-head"><strong>반려 사유</strong><span>본사 · '+resubmission.reviewedAt+'</span></div>'+(rejectionReasons[selected]||resubmission.reason)+'</section>':'')+body+'<div class="detail-note">'+note+'</div><div class="actions"><span class="action-note">'+(selected==='40'?'본사 검토 완료':'증빙을 확인한 뒤 처리해 주세요.')+'</span><div class="buttons">'+actions+'</div></div>';
if(document.querySelector('#accept'))document.querySelector('#accept').onclick=()=>{if(selected==='39'){if(lightConfirmed)return;lightConfirmed=true;document.querySelector('#site-badge').textContent='2';document.querySelector('#completion-count').textContent='0';document.querySelector('#confirmed-count').textContent='2';render();notify('시안: 본사에서 완료를 확인했습니다.');}else notify('시안: 관측 결과를 수락했습니다.');};
if(document.querySelector('#reject'))document.querySelector('#reject').onclick=()=>{document.querySelector('#reject-error').textContent='';document.querySelector('#reject-reason-input').value='';document.querySelector('#reject-dialog').style.display='flex';document.querySelector('#reject-reason-input').focus();};if(document.querySelector('#history'))document.querySelector('#history').onclick=()=>notify('시안: 02.20 본사 완료 확인 · 사진 2장');
if(selected==='45'){document.querySelector('#analysis-view-tab').onclick=()=>{wallView='analysis';render();};document.querySelector('#timeline-view-tab').onclick=()=>{wallView='timeline';render();};}}
document.querySelector('#reject-reason-input').oninput=()=>document.querySelector('#reject-error').textContent='';document.querySelector('#reject-cancel').onclick=()=>document.querySelector('#reject-dialog').style.display='none';document.querySelector('#reject-form').onsubmit=e=>{e.preventDefault();const reason=document.querySelector('#reject-reason-input').value.trim();if(!reason){document.querySelector('#reject-error').textContent='반려 사유를 작성해 주세요.';return;}rejectionReasons[selected]=reason;const t=tasks.find(t=>t.id===selected);t.status='반려';t.tone='amber';if(selected==='39')lightConfirmed=false;document.querySelector('#reject-dialog').style.display='none';render();notify('시안: 반려 사유와 재제출 요청을 남겼습니다.');};
document.querySelector('#report-button').onclick=()=>document.querySelector('#report-sheet').style.display='block';document.querySelector('#report-close').onclick=()=>document.querySelector('#report-sheet').style.display='none';render();
